
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_2d_b86_mgc_HO2D_2_zk():
    # Prepare the input
    inp = test_data["HO2D"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_2d_b86_mgc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-8.488852168226189e-01, -8.489219866925468e-01, -8.489817779142164e-01, -8.490790558653075e-01, -8.492373669833833e-01, -8.494947143437739e-01, -8.499105338154650e-01, -8.505683183795982e-01, -8.515415595999161e-01, -8.526909043557250e-01, -8.528697352813216e-01, -8.476007802521944e-01, -8.244466728640071e-01, -7.592256557841189e-01, -6.264127190654150e-01, -4.362068779461571e-01, -2.275598440260827e-01, -7.286473610821428e-02, -1.430450327758436e-02, -1.450843341484549e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


